        "isCorrect": true,
        "explanation": "Na suspeita de intoxicação ocupacional por agrotóxicos, a equipe da atenção primária deve tratar os sintomas, solicitar exames conforme a avaliação clínica, notificar o caso suspeito no Sinan, emitir atestado quando necessário e solicitar apoio matricial da Vigilância em Saúde do Trabalhador."
